package com.bananalab.lite;
import java.io.*;import java.util.*;
public class Stage33ModelsCheck{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{String root=args[0];PixelGenerator pixel=new PixelGenerator(new FileInputStream(root+"/assets/pixel-v2/character21.bin"));check(pixel.inputs==48&&pixel.hidden==256,"Pixel21 architecture");float max=0;try(DataInputStream in=new DataInputStream(new FileInputStream(root+"/model-source/pixel21-reference.bin"))){int rows=in.readInt(),n=in.readInt();for(int i=0;i<rows;i++){float[] input=new float[n];for(int j=0;j<n;j++)input[j]=in.readFloat();float[] result=pixel.forward(input);for(int j=0;j<4;j++)max=Math.max(max,Math.abs(result[j]-in.readFloat()));}}check(max<.0004,"pixel parity");System.out.println("PIXEL21_PARITY "+max);
 BananaTransformer chat=new BananaTransformer(new FileInputStream(root+"/assets/chat33/chat33.bin"),new FileInputStream(root+"/assets/chat33/vocab.txt"),new FileInputStream(root+"/assets/chat33/tokenizer.json"));check(chat.d==128&&chat.layers==3,"Chat33 architecture");float error=0;try(DataInputStream in=new DataInputStream(new FileInputStream(root+"/model-source/chat33-reference.bin"))){int cases=in.readInt(),v=in.readInt();for(int i=0;i<cases;i++){int n=in.readInt();BananaTransformer.Session session=chat.session();float[] actual=null;for(int j=0;j<n;j++)actual=session.step(in.readInt());for(int j=0;j<v;j++)error=Math.max(error,Math.abs(actual[j]-in.readFloat()));}}check(error<.0004,"chat parity");System.out.println("CHAT33_PARITY "+error);
 for(String name:new String[]{"uma","raquel","dario"}){List<String[]> history=Arrays.asList(new String[]{"crea un gato llamado "+name,"el personaje se llama "+name+" ."},new String[]{"su color es azul",name+" es azul ."},new String[]{"lleva sobretodo","conservo su identidad y agrego el sobretodo ."});System.out.println("RESERVED_NAME "+name+" => "+chat.generate("como se llama",history).text);}
 for(String q:new String[]{"hola","sos independiente","que significa entregar","quiero una idea de detectives"})System.out.println("CHAT "+q+" => "+chat.generate(q,"","").text);
 }
}
